import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../../visualPage/CadastroProfessores.css'; // Importe o arquivo CSS

const CadastroProfessores = () => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [dataCadastro, setDataCadastro] = useState('');
  const [ativo, setAtivo] = useState(true); // Estado para ativo/inativo
  const [idProfessorEditando, setIdProfessorEditando] = useState(null);

  // Função para criar um novo professor
  const criarProfessor = async () => {
    try {
      await axios.post('http://localhost:5000/api/professores', {
        nome,
        email,
        dataCadastro,
        ativo,
      });
      limparCampos();
    } catch (err) {
      console.error('Erro ao criar professor:', err);
    }
  };

  // Função para editar um professor existente
  const editarProfessor = async (id) => {
    try {
      await axios.put(`http://localhost:5000/api/professores/${id}`, {
        nome,
        email,
        dataCadastro,
        ativo,
      });
      limparCampos();
      setIdProfessorEditando(null);
    } catch (err) {
      console.error('Erro ao editar professor:', err);
    }
  };

  // Função para limpar os campos do formulário
  const limparCampos = () => {
    setNome('');
    setEmail('');
    setDataCadastro('');
    setAtivo(true); // Por padrão, ativo
    setIdProfessorEditando(null); // Sai do modo de edição
  };

  return (
    <div className="container-cadastro-professores">
      <h2>Cadastro de Professores</h2>
      <div className="form-cadastro">
        <input
          type="text"
          placeholder="Nome"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="date"
          placeholder="Data de Cadastro"
          value={dataCadastro}
          onChange={(e) => setDataCadastro(e.target.value)}
        />

        <div>
          <label>
            <input
              type="checkbox"
              checked={ativo}
              onChange={(e) => setAtivo(e.target.checked)}
            />
            Ativo
          </label>
        </div>

        <div className="buttons">
          {idProfessorEditando ? (
            <button onClick={() => editarProfessor(idProfessorEditando)}>Salvar</button>
          ) : (
            <button onClick={criarProfessor}>Cadastrar</button>
          )}
          <button onClick={limparCampos}>Cancelar</button>
        </div>
      </div>
    </div>
  );
};

export default CadastroProfessores;
